const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const area=document.createElement('section');area.className='composer research-workspace';area.id='research-workspace';
area.innerHTML=`<div class="composer-top"><div><div class="eyebrow">PUBLIC RESEARCH WORKSPACE</div><h2>Ask. Discover. Download.</h2></div><span class="small-tag">FLEXIBLE FIELDS · TRACEABLE CLAIMS</span></div><p>Describe the dataset you need. EkList checks the institution catalogue, then searches and downloads public sources when needed. Public source excerpts go to NVIDIA for extraction; private uploads stay in their existing workflow.</p><form id="research-form"><label for="research-query">Research objective · Hindi or English</label><textarea id="research-query" rows="3" placeholder="Find organisations working on rural education in Rajasthan, their programmes and university partnerships." required minlength="3" maxlength="2000"></textarea><div class="research-actions"><button class="primary" id="research-start">Build research CSV ↗</button><button type="button" class="secondary" id="research-history">Recent research</button><span>Up to 2 searches · 6 downloads · missing facts stay empty</span></div></form><div id="research-output" aria-live="polite"></div>`;
document.querySelector('.suggestions').after(area);
const button=document.createElement('button');button.className='secondary';button.textContent='◎ Research → CSV';button.onclick=()=>{area.scrollIntoView({behavior:'smooth'});document.querySelector('#research-query').focus()};document.querySelector('.integration-bar').append(button);
let timer=null,active=null;
async function api(url,opts){const r=await fetch(url,opts);const j=await r.json();if(!r.ok)throw Error(j.error||'Research request failed');return j}
function graph(j){
 const edges=j.claims.filter(c=>c.object_id), ids=[...new Set(edges.flatMap(c=>[c.subject_id,c.object_id]))].slice(0,24);
 if(!ids.length)return '';
 const nodes=ids.map((id,i)=>({id,x:340+230*Math.cos(i*2*Math.PI/ids.length),y:210+155*Math.sin(i*2*Math.PI/ids.length),name:j.entities.find(e=>e.id===id)?.name||id}));
 return `<svg class="research-network" viewBox="0 0 680 420" role="img" aria-label="Evidence-linked entity relationships">${edges.map(c=>{const a=nodes.find(n=>n.id===c.subject_id),b=nodes.find(n=>n.id===c.object_id);return a&&b?`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#96b09b" stroke-width="2"><title>${esc(c.predicate)}</title></line>`:''}).join('')}${nodes.map(n=>`<g data-research-entity="${esc(n.id)}" tabindex="0" role="button" aria-label="Inspect ${esc(n.name)}"><circle cx="${n.x}" cy="${n.y}" r="18" fill="#365d48"/><text x="${n.x}" y="${n.y+35}" text-anchor="middle" font-size="11" fill="#243e30">${esc(n.name.slice(0,28))}</text><title>${esc(n.name)}</title></g>`).join('')}</svg><p>First 24 connected entities. Click a node or a relationship below for evidence.</p>`;
}
function render(j){
 const pending=['queued','running'].includes(j.status),rows=j.rows||[],fields=['name','entity_type',...(j.plan?.fields||[])],out=document.querySelector('#research-output');
 document.querySelector('#research-start').disabled=pending;
 out.innerHTML=`<div class="research-status"><span class="pill">${esc(j.status)}</span> <strong>${esc(j.stage)}</strong></div><p>${esc(j.plan?.objective||j.query)}</p><div class="research-metrics"><span>${rows.length} candidate rows</span><span>${j.sources.length} sources saved</span><span>${j.claims.length} claims</span><span>${j.metrics.search_calls} search calls</span><span>${j.metrics.rejected_extractions} rejected extractions</span></div>${j.notice?`<p class="research-note">${esc(j.notice)}</p>`:''}${!pending?`<div class="research-actions">${['results','entities','claims','evidence','sources','gaps'].map(k=>`<a class="${k==='results'?'dark-button':'secondary'}" href="/api/research/jobs/${encodeURIComponent(j.id)}?export=${k}">↓ ${esc(k)}.csv</a>`).join('')}</div>`:''}${rows.length?`<div class="table-scroll"><table><thead><tr>${fields.map(f=>`<th>${esc(f)}</th>`).join('')}<th>EVIDENCE</th></tr></thead><tbody>${rows.map(r=>`<tr>${fields.map(f=>`<td>${esc(r[f]||'Not found')}</td>`).join('')}<td><button class="secondary" data-research-entity="${esc(r.entity_id)}">Inspect claims</button></td></tr>`).join('')}</tbody></table></div>`:pending?'<p>Retrieving sources; results appear as extraction completes.</p>':'<p>No supported rows extracted. Check the source failures and gaps below; no data was invented.</p>'}<div id="research-evidence"></div><details><summary>Evidence-linked graph · ${j.claims.filter(c=>c.object_id).length} relationships</summary>${graph(j)}<div class="research-graph">${j.claims.filter(c=>c.object_id).map(c=>`<button class="research-edge" data-research-entity="${esc(c.subject_id)}"><b>${esc(j.entities.find(e=>e.id===c.subject_id)?.name)}</b><span> → ${esc(c.predicate)} → </span><b>${esc(j.entities.find(e=>e.id===c.object_id)?.name)}</b><small>Text located · unreviewed · inspect evidence</small></button>`).join('')||'<p>No supported relationship candidates extracted.</p>'}</div></details><details><summary>Sources and gaps (${j.gaps.length})</summary>${j.sources.map(s=>`<p><strong>${esc(s.title)}</strong><br>${/^https?:\/\//.test(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.url)}</a>`:esc(s.url)}<br><small>${esc(s.retrieved_at)} · SHA256 ${esc(s.sha256)}</small></p>`).join('')}${j.gaps.map(g=>`<p class="research-note">${esc(g.source||'Coverage')}: ${esc(g.reason)}</p>`).join('')}</details>`;
 out.querySelectorAll('[data-research-entity]').forEach(b=>{b.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();b.dispatchEvent(new MouseEvent('click'))}};b.onclick=()=>{
  const entity=j.entities.find(e=>e.id===b.dataset.researchEntity),cs=j.claims.filter(c=>c.subject_id===entity.id||c.object_id===entity.id);
  const panel=document.querySelector('#research-evidence');panel.innerHTML=`<h3>${esc(entity.name)} · source evidence</h3>`+cs.map(c=>{const ev=j.evidence.find(e=>e.id===c.evidence_id);return `<article class="source-card"><strong>${esc(c.predicate)}: ${esc(c.value)}</strong><p>Text located · unreviewed</p><blockquote>${esc(ev.quote)}</blockquote><small>${esc(ev.locator)} · ${esc(ev.retrieved_at)}</small><p>${/^https?:\/\//.test(ev.source_url)?`<a href="${esc(ev.source_url)}" target="_blank" rel="noreferrer">Open original source ↗</a>`:esc(ev.source_url)}</p></article>`}).join('');panel.scrollIntoView({behavior:'smooth',block:'nearest'});
 }});
}
async function poll(id){try{const j=await api('/api/research/jobs/'+id);if(active!==id)return;render(j);if(['queued','running'].includes(j.status))timer=setTimeout(()=>poll(id),1800)}catch(ex){document.querySelector('#research-output').textContent=ex.message;document.querySelector('#research-start').disabled=false}}
document.querySelector('#research-form').onsubmit=async ev=>{ev.preventDefault();clearTimeout(timer);document.querySelector('#research-start').disabled=true;try{const j=await api('/api/research/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:document.querySelector('#research-query').value})});active=j.id;localStorage.setItem('eklist-research-job',j.id);await poll(j.id)}catch(ex){document.querySelector('#research-output').textContent=ex.message;document.querySelector('#research-start').disabled=false}};
document.querySelector('#research-history').onclick=async()=>{try{const {jobs}=await api('/api/research/jobs');const out=document.querySelector('#research-output');out.innerHTML='<h3>Recent research</h3>'+jobs.map(j=>`<p><button class="secondary" data-job="${esc(j.id)}">${esc(j.query)} · ${esc(j.status)}</button></p>`).join('');out.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{clearTimeout(timer);active=b.dataset.job;poll(active)})}catch(ex){document.querySelector('#research-output').textContent=ex.message}};
const previous=localStorage.getItem('eklist-research-job');if(previous){active=previous;poll(previous)}
